package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles document search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req struct {
		Query      string `json:"query"`
		Owner      string `json:"owner"`
		Classifier string `json:"classifier"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Sanitize query - remove dangerous characters
	req.Query = strings.ReplaceAll(req.Query, ";", "")
	req.Query = strings.ReplaceAll(req.Query, "/*", "")
	req.Query = strings.ReplaceAll(req.Query, "*/", "")

	// Build search query with owner filter
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE 1=1"

	if req.Query != "" {
		baseQuery += fmt.Sprintf(" AND (title ILIKE '%%%s%%' OR content ILIKE '%%%s%%')", req.Query, req.Query)
	}

	if req.Owner != "" {
		baseQuery += fmt.Sprintf(" AND owner_id = %s", req.Owner)
	}

	// Classification filter uses allowlist validation
	allowedClassifiers := map[string]bool{"public": true, "internal": true, "confidential": true}
	if req.Classifier != "" && allowedClassifiers[strings.ToLower(req.Classifier)] {
		baseQuery += fmt.Sprintf(" AND classification = '%s'", req.Classifier)
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
